window.docContents[1].resolve({"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Representation-of-a-Lie-algebra-via-its-universal-enveloping-algebra/#Chapter2___Exercise2___9___11":{"contents":"Exercise 2.9.11. Explain why a representation of a Lie algebra is the same thing as a representation of its universal enveloping algebra.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.9. Lie algebras\tRepresentation of a Lie algebra via its universal enveloping algebra","header":"Representation of a Lie algebra via its universal enveloping algebra","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Representation-of-a-Lie-algebra-via-its-universal-enveloping-algebra/#Chapter2___Exercise2___9___11"},"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Start-of-proof-of-Theorem-5___15___1-_LPAR_Frobenius-character-formula_RPAR_/#Chapter5___Discussion_proof_of_Theorem5___15___1":{"contents":"Proof. For brevity denote \\chi_{V_\\lambda} by \\chi_\\lambda. Let us denote the class function defined in the theorem by \\theta_\\lambda. We claim that this function has the property \\theta_\\lambda = \\sum_{\\mu \\geq \\lambda} L_{\\mu\\lambda} \\chi_\\mu, where L_{\\mu\\lambda} are integers and L_{\\lambda\\lambda} = 1. Indeed, from Theorem 5.14.3 we have\n\n\\theta_\\lambda = \\sum_{\\sigma \\in S_N} (-1)^\\sigma \\chi_{U_{\\lambda + \\rho - \\sigma(\\rho)}},\n\nwhere if the vector \\lambda + \\rho - \\sigma(\\rho) has a negative entry, the corresponding term is dropped, and if it has nonnegative entries which fail to be nonincreasing, then the entries should be reordered in nonincreasing order, making a partition that we'll denote by \\langle\\lambda + \\rho - \\sigma(\\rho)\\rangle (i.e., we\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.15. The Frobenius character formula\tStart of proof of Theorem 5.15.1 (Frobenius character formula)","header":"Start of proof of Theorem 5.15.1 (Frobenius character formula)","id":"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Start-of-proof-of-Theorem-5___15___1-_LPAR_Frobenius-character-formula_RPAR_/#Chapter5___Discussion_proof_of_Theorem5___15___1"},"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Section-5___23___-Algebraic-representations-of-GL_LPAR_V_RPAR_/#Chapter5___Introduction_5___23":{"contents":"\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.23. Algebraic representations of $GL(V)$\tSection 5.23: Algebraic representations of GL(V)","header":"Section 5.23: Algebraic representations of GL(V)","id":"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Section-5___23___-Algebraic-representations-of-GL_LPAR_V_RPAR_/#Chapter5___Introduction_5___23"},"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Tor-functors/#Chapter8___Definition8___2___3":{"contents":"Definition 8.2.3. Let M be a right A-module, P_\\bullet a projective resolution of M, and N a left A-module. For i \\geq 0 we define \\mathrm{Tor}_i^A(M, N) = \\mathrm{Tor}_i(M, N) to be the ith cohomology of the complex\n\n\\cdots \\to P_2 \\otimes_A N \\to P_1 \\otimes_A N \\to P_0 \\otimes_A N \\to 0\n\ninduced by the resolution P_\\bullet.\n\n\n\n","context":"Introduction to Representation Theory\t8. Homological algebra\t8.2. Tor and Ext functors\tTor functors","header":"Tor functors","id":"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Tor-functors/#Chapter8___Definition8___2___3"}});
